func resolveSlot(name, path string, ctx *Boards, out *Slot) error {
	e1, ok2 := ctx.rows.Find(out.home_id)
	if !ok2 {
		return fmt.Errorf("%s: %shome: no entry %v", name, path, out.home_id)
	}
	out.home = e1
	return nil
}

func resolveBoard(name, path string, ctx *Boards, out *Board) error {
	for k2, x1 := range out.slots.All() {
		kp3 := jsonKeyPath(path+"slots.", k2)
		if x1 != nil {
			if err := resolveSlot(name, kp3+".", ctx, x1); err != nil {
				return err
			}
		}
	}
	for k5, x4 := range out.byLit.All() {
		kp6 := jsonKeyPath(path+"byLit.", k5)
		if x4 != nil {
			if err := resolveSlot(name, kp6+".", ctx, x4); err != nil {
				return err
			}
		}
	}
	for k8 := range out.byBoard.All() {
		kp9 := jsonKeyPath(path+"byBoard.", string(k8))
		if _, ok10 := ctx.rows.Find(k8); !ok10 {
			return fmt.Errorf("%s: %s: no entry %v", name, kp9, string(k8))
		}
	}
	for k12, x11 := range out.rankSlots.All() {
		kp13 := jsonKeyPath(path+"rankSlots.", strconv.FormatInt(int64(k12.Code()), 10))
		if x11 != nil {
			if err := resolveSlot(name, kp13+".", ctx, x11); err != nil {
				return err
			}
		}
	}
	for k15, x14 := range out.elemSlots.All() {
		kp16 := jsonKeyPath(path+"elemSlots.", k15.Wire())
		if x14 != nil {
			if err := resolveSlot(name, kp16+".", ctx, x14); err != nil {
				return err
			}
		}
	}
	for k18 := range out.byBoardTotals.All() {
		kp19 := jsonKeyPath(path+"$byBoardTotals.", string(k18))
		if _, ok20 := ctx.rows.Find(k18); !ok20 {
			return fmt.Errorf("%s: %s: no entry %v", name, kp19, string(k18))
		}
	}
	for j21, k22 := range [...]string{"plain", "series-1"} {
		for k24 := range out.perTone[j21].All() {
			kp25 := jsonKeyPath(fmt.Sprintf("%s$perTone.%s.", path, k22), string(k24))
			if _, ok26 := ctx.rows.Find(k24); !ok26 {
				return fmt.Errorf("%s: %s: no entry %v", name, kp25, string(k24))
			}
		}
	}
	return nil
}

func loadBoards(path string, out *Boards) error {
	f, err := rt.ReadDataFile(path, BoardsSchema)
	if err != nil {
		return err
	}
	if f.Rows == nil {
		return rt.Missing(path, "", "rows")
	}
	var rows []json.RawMessage
	if err := jsonRead(path, "", "rows", f.Rows, &rows); err != nil {
		return err
	}
	values := make([]Board, len(rows))
	keys := make([]BoardID, len(rows))
	for i, raw := range rows {
		id, retired, err := jsonRowID(path, fmt.Sprintf("rows[%d].", i), raw)
		if err != nil {
			return err
		}
		if err := decodeBoard(path, fmt.Sprintf("rows[%d].", i), raw, &values[i]); err != nil {
			return err
		}
		values[i].id, values[i].retired = BoardID(id), retired
		keys[i] = values[i].id
	}
	if at, first, ok := rt.FirstDup(keys); ok {
		return rt.DupRow(path, fmt.Sprintf("rows[%d].", at), "$id", rt.WireToken(string(keys[at])), fmt.Sprintf("rows[%d]", first))
	}
	out.rows = rt.MakeKeyedList(values, keys)
	for i := range out.rows.Len() {
		if err := resolveBoard(path, fmt.Sprintf("rows[%d].", i), out, out.rows.At(i)); err != nil {
			return err
		}
	}
	return nil
}
